(()=>{
'use strict';
const VERSION='7.3.3';
const LOGO='data:image/png;base64,';
const fmt=v=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(Number(v)||0);

function st(){try{return state}catch(_){return null}}
function sd(){try{return stockData}catch(_){return window.STOCK_DATA||{snapshots:{},availableDates:[]}}}
function stockObj(){try{return stock}catch(_){return null}}

function installLogo(){
  const box=document.querySelector('.logo-box');
  if(!box)return;
  let img=box.querySelector('img.v733-logo');
  if(!img){
    box.replaceChildren();
    img=document.createElement('img');
    img.className='v733-logo';
    img.alt='PRIMA';
    box.appendChild(img);
  }
  if(img.src!==LOGO)img.src=LOGO;
}

function getFilteredLastDate(){
  const s=st();
  const dates=(s?.filtered||[]).map(r=>r.Date).filter(Boolean).sort();
  return dates.at(-1)||document.getElementById('dateTo')?.value||'';
}

function renderFilteredStock(){
  const data=sd();
  const target=getFilteredLastDate();
  const dates=(data.availableDates||[]).filter(d=>!target||d<=target).sort();
  const selected=dates.at(-1)||'';
  const snap=selected?(data.snapshots||{})[selected]:null;
  const truckFilter=document.getElementById('truckFilter')?.value||'';
  const fs={...(snap?.fuelStorage||{})};
  const ft={...(snap?.fuelTruck||{})};
  if(truckFilter){
    Object.keys(ft).forEach(k=>{if(k!==truckFilter)delete ft[k]});
  }
  const fsTotal=Object.values(fs).reduce((a,b)=>a+(Number(b)||0),0);
  const ftTotal=Object.values(ft).reduce((a,b)=>a+(Number(b)||0),0);
  const total=fsTotal+ftTotal;

  const s=stockObj();
  if(s){
    s.fuelStorage=fs;s.fuelTruck=ft;s.total=total;s.snapshotDate=selected;s.snapshotTime=snap?.time||snap?.snapshotTime||'';
  }

  const day=document.getElementById('stockDay');
  const date=document.getElementById('stockDate');
  const time=document.getElementById('stockTime');
  if(day)day.textContent=selected?new Intl.DateTimeFormat('id-ID',{weekday:'long'}).format(new Date(selected+'T00:00:00')):'-';
  if(date)date.textContent=selected?new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'long',year:'numeric'}).format(new Date(selected+'T00:00:00')):'-';
  if(time)time.textContent=(snap?.time||snap?.snapshotTime||'-')+' WITA';

  const storageList=document.getElementById('storageList');
  if(storageList)storageList.innerHTML=Object.entries(fs).reverse().map(([k,v])=>`<div class="stock-row"><b>${k}</b><div class="bar-track"><div class="bar-fill" style="width:${total?Math.min(100,(Number(v)||0)/total*100):0}%"></div></div><span class="stock-value">${Number(v)?fmt(v):'-'}</span></div>`).join('');

  const truckList=document.getElementById('truckStockList');
  if(truckList){
    const max=Math.max(1,...Object.values(ft).map(Number));
    truckList.innerHTML=Object.entries(ft).reverse().map(([k,v])=>`<div class="stock-row"><b>${k}</b><div class="bar-track"><div class="bar-fill" style="width:${(Number(v)||0)/max*100}%"></div></div><span class="stock-value">${Number(v)?fmt(v):'-'}</span></div>`).join('');
  }

  const totalWrap=document.querySelector('.stock-panel .stock-total');
  if(totalWrap&&truckList){
    totalWrap.classList.add('v733-stock-total');
    const truckCol=truckList.parentElement;
    if(totalWrap.parentElement!==truckCol)truckCol.appendChild(totalWrap);
    totalWrap.innerHTML=`<small>TOTAL STOCK</small><div class="stock-orb"><strong id="stockTotal">${fmt(total)}</strong><span>Liter</span></div>`;
  }
}

function enforceDailyChart(){
  const s=st(), c=s?.charts?.daily, canvas=document.getElementById('dailyChart');
  if(!canvas)return;
  const wrap=canvas.parentElement;
  if(wrap){wrap.style.height='184px';wrap.style.minHeight='184px';wrap.style.position='relative';}
  if(c){
    try{
      c.options.responsive=true;
      c.options.maintainAspectRatio=false;
      c.options.animation=false;
      c.resize();
      c.update('none');
    }catch(err){console.warn('daily resize',err)}
  } else if(typeof renderCharts==='function'){
    try{renderCharts()}catch(err){console.warn('daily rebuild',err)}
  }
}

function refreshAfterCore(){
  renderFilteredStock();
  installLogo();
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    enforceDailyChart();
    const charts=st()?.charts||{};
    ['shift','truck','status','cat'].forEach(name=>{
      const c=charts[name];
      if(!c)return;
      try{c.options.animation=false;c.resize();c.update('none')}catch(_){}
    });
  }));
}

function runFilter(){
  if(typeof applyFilters==='function'){
    applyFilters();
    refreshAfterCore();
  }
}

function bindSinglePipeline(){
  const ids=['dateFrom','dateTo','shiftFilter','categoryFilter','truckFilter'];
  ids.forEach(id=>{
    const old=document.getElementById(id);
    if(!old)return;
    const clone=old.cloneNode(true);clone.value=old.value;old.replaceWith(clone);
    clone.addEventListener('change',runFilter);
  });
  const oldSearch=document.getElementById('unitSearch');
  if(oldSearch){
    const clone=oldSearch.cloneNode(true);clone.value=oldSearch.value;oldSearch.replaceWith(clone);
    let t;clone.addEventListener('input',()=>{clearTimeout(t);t=setTimeout(runFilter,100)});
  }
  const oldReset=document.getElementById('resetBtn');
  if(oldReset){
    const clone=oldReset.cloneNode(true);oldReset.replaceWith(clone);
    clone.addEventListener('click',()=>{
      if(typeof initFilters==='function')initFilters();
      const q=document.getElementById('unitSearch');if(q)q.value='';
      runFilter();
    });
  }
}

function exportExcel(){
  if(!window.XLSX)return alert('Library Excel belum siap.');
  const s=st(), rows=[...(s?.filtered||[])];
  const from=document.getElementById('dateFrom')?.value||'', to=document.getElementById('dateTo')?.value||'';
  const wb=XLSX.utils.book_new();
  const total=rows.reduce((a,r)=>a+(Number(r.Fuel_Liter)||0),0);
  const days=new Set(rows.map(r=>r.Date)).size;
  const units=new Set(rows.map(r=>r.Unit_Code)).size;
  const av=rows.map(r=>Number(r.Actual_LHM)).filter(v=>Number.isFinite(v)&&v>0);
  const avg=av.length?av.reduce((a,b)=>a+b,0)/av.length:0;
  const summary=[
    ['FUEL MANAGEMENT SYSTEM - DASHBOARD EXPORT',''],
    ['PT PRIMA SARANA GEMILANG SITE ABM',''],
    ['PERIOD FROM',from],['PERIOD TO',to],
    ['SHIFT',document.getElementById('shiftFilter')?.value||'All Shift'],
    ['CATEGORY',document.getElementById('categoryFilter')?.value||'All Category'],
    ['FUEL TRUCK',document.getElementById('truckFilter')?.value||'All Fuel Truck'],
    ['SEARCH UNIT',document.getElementById('unitSearch')?.value||''],
    ['TOTAL FUEL ISSUED',total],['AVERAGE / DAY',days?total/days:0],['ACTIVE UNIT',units],['AVG ACTUAL L/HM',avg]
  ];
  XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(summary),'Dashboard Summary');
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Fuel Usage');
  XLSX.writeFile(wb,`Fuel_Dashboard_${from||'start'}_${to||'end'}.xlsx`);
}

function installExcelExport(){
  const old=document.getElementById('exportBtn');
  if(old){
    const b=old.cloneNode(true);b.innerHTML='⇩<span>EXPORT EXCEL</span>';old.replaceWith(b);b.addEventListener('click',exportExcel);
  }
}

function setVersion(){
  const v=document.querySelector('.v7-version');if(v)v.textContent='Dashboard V'+VERSION+' Stable';
}

function boot(){
  installLogo();
  bindSinglePipeline();
  installExcelExport();
  runFilter();
  setVersion();
  const ro=new ResizeObserver(()=>requestAnimationFrame(enforceDailyChart));
  const trend=document.querySelector('.trend-panel');
  if(trend)ro.observe(trend);
  window.addEventListener('resize',()=>requestAnimationFrame(enforceDailyChart),{passive:true});
  window.addEventListener('pageshow',()=>setTimeout(()=>{installLogo();runFilter()},50));
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(()=>{installLogo();refreshAfterCore()},50)});
}
boot();
})();
